&lt;h2 data-section-id=&quot;lrovnr&quot; data-start=&quot;2482&quot; data-end=&quot;2503&quot;&gt;&lt;strong data-start=&quot;2485&quot; data-end=&quot;2503&quot;&gt;Qualifications&lt;/strong&gt;&lt;/h2&gt;
&lt;ul data-start=&quot;2504&quot; data-end=&quot;3161&quot;&gt;
&lt;li data-section-id=&quot;t1e39r&quot; data-start=&quot;2504&quot; data-end=&quot;2607&quot;&gt;Bachelor’s degree in Human Resources, Business Administration, or related field (Master’s preferred).&lt;/li&gt;
&lt;li data-section-id=&quot;1j1x1zz&quot; data-start=&quot;2608&quot; data-end=&quot;2726&quot;&gt;&lt;strong data-start=&quot;2610&quot; data-end=&quot;2653&quot;&gt;8–10 years of progressive HR experience&lt;/strong&gt;, with &lt;strong data-start=&quot;2660&quot; data-end=&quot;2725&quot;&gt;strong manufacturing or plant environment experience required&lt;/strong&gt;.&lt;/li&gt;
&lt;li data-section-id=&quot;smqfcf&quot; data-start=&quot;2727&quot; data-end=&quot;2827&quot;&gt;Proven experience supporting &lt;strong data-start=&quot;2758&quot; data-end=&quot;2805&quot;&gt;high-growth, ramp-up, or startup operations&lt;/strong&gt; (strongly preferred).&lt;/li&gt;
&lt;li data-section-id=&quot;158a821&quot; data-start=&quot;2828&quot; data-end=&quot;2886&quot;&gt;Deep knowledge of employment laws and HR best practices.&lt;/li&gt;
